import { useInsertionEffect, useMemo, type CSSProperties, type HTMLAttributes } from "react";

export interface GradientStop {
  position: number;
  color: string;
}

export type GradientPresetName =
  | "sunrise"
  | "bubble"
  | "peach"
  | "tonic"
  | "mint"
  | "spring"
  | "twilight"
  | "bay";

export type GradientInput = readonly GradientStop[] | GradientPresetName;
export type SpinPattern = "arrow-up" | "diagonal" | "snake" | "ripple";

export interface GradientSpinProps extends HTMLAttributes<HTMLSpanElement> {
  /** Multi-stop gradient or a built-in preset. */
  gradient?: GradientInput;
  /** Shape of the brightness wave travelling across the grid. */
  pattern?: SpinPattern;
  /** Number of grid rows. */
  rows?: number;
  /** Number of grid columns. */
  cols?: number;
  /** Cell edge length in pixels. */
  cellSize?: number;
  /** Gap between cells in pixels. */
  cellGap?: number;
  /** Cell corner radius in pixels. */
  cellRadius?: number;
  /** Duration of one wave sweep in milliseconds. */
  period?: number;
  /** Resting opacity of cells outside the wavefront. */
  dim?: number;
  /** Maps the gradient top-to-bottom or along the wave path. */
  colorBy?: "path" | "row";
  /** Accessible status label. */
  label?: string;
  /** Freezes the animation when reduced motion is requested. */
  respectReducedMotion?: boolean;
}

export const spinPatterns: readonly SpinPattern[] = ["arrow-up", "diagonal", "snake", "ripple"];

export const gradientPresets: Record<GradientPresetName, readonly GradientStop[]> = {
  sunrise: [
    { color: "#B6D3EF", position: 0 },
    { color: "#CAD1D7", position: 0.153 },
    { color: "#D7CFC8", position: 0.252 },
