    { color: "#154288", position: 0.79 },
    { color: "#262C81", position: 1 },
  ],
};

const STYLE_ID = "boring-ui-gradient-spin-styles";
const SCROLL_BAND = 4;

const STYLE_TEXT = `@keyframes boring-ui-gradient-spin-pulse {
  0% { opacity: 1; }
  45% { opacity: var(--gradient-spin-dim, 0.1); }
  92% { opacity: var(--gradient-spin-dim, 0.1); }
  100% { opacity: 1; }
}
.boring-ui-gradient-spin-cell {
  opacity: var(--gradient-spin-dim, 0.1);
  animation: boring-ui-gradient-spin-pulse var(--gradient-spin-period, 750ms) linear infinite;
  animation-delay: calc((var(--gradient-spin-phase, 0) - 1) * var(--gradient-spin-period, 750ms));
}
@media (prefers-reduced-motion: reduce) {
  [data-gradient-spin-reduced-motion="respect"] .boring-ui-gradient-spin-cell {
    animation: none;
    opacity: 0.6;
  }
}`;

function useInjectedStyles() {
  useInsertionEffect(() => {
    if (typeof document === "undefined" || document.getElementById(STYLE_ID)) return;
    const element = document.createElement("style");
    element.id = STYLE_ID;
    element.textContent = STYLE_TEXT;
    document.head.appendChild(element);
  }, []);
}

function cellWaveOrder(pattern: SpinPattern, row: number, col: number, rows: number, cols: number) {
  const centerCol = (cols - 1) / 2;

  switch (pattern) {
    case "arrow-up":
      return {
        d: rows - 1 - row + Math.abs(col - centerCol),
        max: rows - 1 + centerCol,
      };
    case "diagonal":
      return { d: (row + col) % SCROLL_BAND, max: SCROLL_BAND - 1 };
    case "snake": {
      const rowFromBottom = rows - 1 - row;
      const leftToRight = rowFromBottom % 2 === 0;
      const path = rowFromBottom * cols + (leftToRight ? col : cols - 1 - col);
      return { d: path % SCROLL_BAND, max: SCROLL_BAND - 1 };
    }
    case "ripple": {
      const centerRow = (rows - 1) / 2;
      return {
        d: Math.max(Math.abs(row - centerRow), Math.abs(col - centerCol)),
        max: Math.max(centerRow, centerCol),
      };
    }
  }
}

function hexChannel(hex: string, offset: number) {
  return Number.parseInt(hex.slice(offset, offset + 2), 16);
}

function srgbToLinear(value: number) {
  return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
}

function linearToSrgb(value: number) {
  const clamped = Math.min(Math.max(value, 0), 1);
  return clamped <= 0.0031308 ? clamped * 12.92 : 1.055 * clamped ** (1 / 2.4) - 0.055;
}

interface Oklab {
  l: number;
  a: number;
  b: number;
}

function hexToOklab(hex: string): Oklab {
  const normalized = hex.replace(/^#/, "");
  const expanded =
    normalized.length === 3
      ? normalized
          .split("")
          .map((character) => `${character}${character}`)
          .join("")
      : normalized;
  const red = srgbToLinear(hexChannel(expanded, 0) / 255);
  const green = srgbToLinear(hexChannel(expanded, 2) / 255);
  const blue = srgbToLinear(hexChannel(expanded, 4) / 255);
  const lmsL = Math.cbrt(0.4122214708 * red + 0.5363325363 * green + 0.0514459929 * blue);
  const lmsM = Math.cbrt(0.2119034982 * red + 0.6806995451 * green + 0.1073969566 * blue);
  const lmsS = Math.cbrt(0.0883024619 * red + 0.2817188376 * green + 0.6299787005 * blue);
  return {
    l: 0.2104542553 * lmsL + 0.793617785 * lmsM - 0.0040720468 * lmsS,
    a: 1.9779984951 * lmsL - 2.428592205 * lmsM + 0.4505937099 * lmsS,
    b: 0.0259040371 * lmsL + 0.7827717662 * lmsM - 0.808675766 * lmsS,
  };
}

function oklabToRgbString({ l, a, b }: Oklab) {
  const lmsL = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const lmsM = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const lmsS = (l - 0.0894841775 * a - 1.291485548 * b) ** 3;
  const red = linearToSrgb(4.0767416621 * lmsL - 3.3077115913 * lmsM + 0.2309699292 * lmsS);
  const green = linearToSrgb(-1.2684380046 * lmsL + 2.6097574011 * lmsM - 0.3413193965 * lmsS);
  const blue = linearToSrgb(-0.0041960863 * lmsL - 0.7034186147 * lmsM + 1.707614701 * lmsS);
  return `rgb(${Math.round(red * 255)}, ${Math.round(green * 255)}, ${Math.round(blue * 255)})`;
}

export function sampleGradient(stops: readonly GradientStop[], t: number) {
  if (stops.length === 0) return "currentColor";
  const sorted = [...stops].sort((a, b) => a.position - b.position);
  const clamped = Math.min(Math.max(t, sorted[0].position), sorted[sorted.length - 1].position);
  let lower = sorted[0];
  let upper = sorted[sorted.length - 1];

  for (let index = 0; index < sorted.length - 1; index++) {
    if (clamped >= sorted[index].position && clamped <= sorted[index + 1].position) {
      lower = sorted[index];
      upper = sorted[index + 1];
      break;
    }
  }

  const span = upper.position - lower.position;
  const mix = span === 0 ? 0 : (clamped - lower.position) / span;
  const from = hexToOklab(lower.color);
  const to = hexToOklab(upper.color);
  return oklabToRgbString({
    l: from.l + (to.l - from.l) * mix,
    a: from.a + (to.a - from.a) * mix,
    b: from.b + (to.b - from.b) * mix,
  });
}

export function GradientSpin({
  gradient = "sunrise",
  pattern = "arrow-up",
  rows = 3,
  cols = 3,
  cellSize = 4,
  cellGap = 2,
  cellRadius = 1,
  period = 750,
  dim = 0.1,
  colorBy = "row",
  label = "Loading",
  respectReducedMotion = true,
  className,
  style,
  ...rest
}: GradientSpinProps) {
  useInjectedStyles();

  const stops = typeof gradient === "string" ? gradientPresets[gradient] : gradient;
  const cells = useMemo(() => {
    const seeds: Array<{ row: number; col: number; d: number; max: number }> = [];
    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        seeds.push({ row, col, ...cellWaveOrder(pattern, row, col, rows, cols) });
      }
    }

    const pathRank = new Map<string, number>();
    if (colorBy === "path") {
      const ordered = [...seeds].sort(
        (left, right) => left.d - right.d || left.row - right.row || left.col - right.col,
      );
      ordered.forEach((seed, index) => pathRank.set(`${seed.row}-${seed.col}`, index));
    }

    return seeds.map((seed) => {
      const key = `${seed.row}-${seed.col}`;
      const phase = seed.max === 0 ? 0 : seed.d / (seed.max + 1);
      const colorPosition =
        colorBy === "path"
          ? seeds.length > 1
            ? (pathRank.get(key) ?? 0) / (seeds.length - 1)
            : 0
          : rows > 1
            ? seed.row / (rows - 1)
            : 0;
      return { key, color: sampleGradient(stops, colorPosition), phase };
    });
  }, [colorBy, cols, pattern, rows, stops]);

  const rootStyle: CSSProperties & Record<string, string | number> = {
    display: "inline-grid",
    gridTemplateColumns: `repeat(${cols}, ${cellSize}px)`,
    gridAutoRows: `${cellSize}px`,
    gap: `${cellGap}px`,
    ...style,
    "--gradient-spin-period": `${period}ms`,
    "--gradient-spin-dim": dim,
  };

  return (
    <span
      role="status"
      aria-label={label}
      data-gradient-spin-reduced-motion={respectReducedMotion ? "respect" : "ignore"}
      className={className}
      style={rootStyle}
      {...rest}
    >
      {cells.map((cell) => (
        <span
          key={cell.key}
          aria-hidden="true"
          className="boring-ui-gradient-spin-cell"
          data-corner-shape={cellRadius >= cellSize / 2 ? "round" : undefined}
          style={
            {
              backgroundColor: cell.color,
              borderRadius: `${cellRadius}px`,
              "--gradient-spin-phase": cell.phase,
            } as CSSProperties
          }
        />
      ))}
    </span>
  );
}
